use crate::game::Result;
use sunrise_sim::mobs::MobEvent;

pub trait MobsCreaturesSideGameExt<'__sg>: crate::game::SideGame<'__sg> {
    fn side_handle_mob_events_reusable(&mut self, events: &mut Vec<MobEvent>) -> Result<()> {
        <Self::State as SideOps>::side_handle_mob_events_reusable(self, events)
    }
}
impl<'__sg, T: crate::game::SideGame<'__sg>> MobsCreaturesSideGameExt<'__sg> for T {}

// Generated by Shape G codemod from side_* role dispatchers.
pub trait SideOps: Sized {
    type Game<'g>;

    fn side_handle_mob_events_reusable(
        game: &mut Self::Game<'_>,
        events: &mut Vec<MobEvent>,
    ) -> Result<()>;
}
